package io.github.jesterportfolio.hearth.verification;

import io.github.jesterportfolio.hearth.survival.economy.*;
import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.bukkit.*;
import org.bukkit.plugin.java.JavaPlugin;

/** 실제 주기 Tick/PG/선택형 실제 LLM을 검증합니다. Player·거래·인벤토리를 합성하지 않습니다. */
public final class MarketVerification {
 private MarketVerification(){}
 private static void check(JavaPlugin p,boolean ok,String name){if(!ok)throw new IllegalStateException("MARKET_CHECK_"+name);p.getLogger().info("HEARTH_MARKET_CHECK PASS "+name);}
 private static <T>CompletionStage<T> on(CompletionStage<T> work,Executor owner){return work.thenApplyAsync(v->v,owner);}
 private static CompletionStage<Void> waitFor(JavaPlugin p,BooleanSupplier test,int ticks,int limit){if(test.getAsBoolean())return CompletableFuture.completedFuture(null);if(ticks>=limit)return CompletableFuture.failedFuture(new IllegalStateException("MARKET_PROBE_TIMEOUT"));var result=new CompletableFuture<Void>();Bukkit.getScheduler().runTaskLater(p,()->waitFor(p,test,ticks+1,limit).whenComplete((v,error)->{if(error==null)result.complete(null);else result.completeExceptionally(error);}),1);return result;}
 public static CompletionStage<Void> run(JavaPlugin p,SurvivalEconomy e,PostgresProgressStore db,String action){final Path root;try{if(!Set.of("prepare","resume","ai").contains(action))throw new IllegalArgumentException();root=IsolatedPaths.require(Path.of(System.getProperty("hearth.market.verification.root","")),"hearth-native-economy-run.");if(!Files.readString(root.resolve(".hearth-market-isolated")).equals("Hearth market isolated v1\n")||!Path.of("").toRealPath().equals(root.resolve("server"))||!Bukkit.getOnlinePlayers().isEmpty()||e.phase()!=SurvivalEconomy.Phase.READY||!Bukkit.getOnlineMode()||!Bukkit.hasWhitelist()||!Bukkit.getIp().equals("127.0.0.1"))throw new IllegalStateException("MARKET_PROBE_GATE");Files.createFile(root.resolve("market-probe-"+action+".started"));}catch(Exception error){return CompletableFuture.failedFuture(error);}return on(db.module("market_probe_directory",c->{try(var st=c.createStatement();var row=st.executeQuery("SHOW data_directory")){if(!row.next()||!Path.of(row.getString(1)).toRealPath().equals(root.resolve("data")))throw new IllegalStateException("MARKET_DATABASE_ROOT");}return null;}),e.owner).thenCompose(v->switch(action){case "prepare"->prepare(p,e,db);case "resume"->resume(p,e,root);default->ai(p,e,db,root);});}
 private static CompletionStage<Void> shock(SurvivalEconomy e,PostgresProgressStore db,long id){return on(e.store.event(e.settings.realm(),new UUID(0x4d41524b,id),"mine_collapse"),e.owner).thenCompose(v->on(db.module("market_owned_fixture_shortage",c->{c.setAutoCommit(false);try{try(var st=c.prepareStatement("SELECT tick FROM hearth_economy.realm WHERE realm_id=? FOR UPDATE")){st.setObject(1,e.settings.realm());st.executeQuery().close();}try(var st=c.prepareStatement("UPDATE hearth_economy.market SET stock=0,revision=revision+1 WHERE realm_id=? AND region_id='mine' AND good_id='iron_ore'")){st.setObject(1,e.settings.realm());if(st.executeUpdate()!=1)throw new IllegalStateException("MARKET_FIXTURE_CELL");}c.commit();return null;}catch(Exception error){c.rollback();throw error;}finally{c.setAutoCommit(true);}}),e.owner));}
 private static CompletionStage<Void> prepare(JavaPlugin p,SurvivalEconomy e,PostgresProgressStore db){return waitFor(p,()->e.market().cursor().tick()>=e.market().opened().tick()+2,0,240).thenRun(()->check(p,true,"actual_scheduled_ticks_advance_without_manual_console_tick_commands")).thenCompose(v->shock(e,db,1)).thenCompose(v->waitFor(p,()->e.market().cursor().mode()==MarketAutomation.Mode.CONSERVE,0,300)).thenCompose(v->on(e.store.modeHistory(e.settings.realm(),20),e.owner)).thenAccept(history->check(p,history.stream().anyMatch(row->row.after()==MarketAutomation.Mode.CONSERVE&&row.source()==MarketAutomation.Source.RULE),"shortage_triggers_persisted_conservation_through_rule_agent_hysteresis"))
  .thenCompose(v->on(db.module("market_no_wallet_writes",c->{try(var st=c.prepareStatement("SELECT count(*) FROM hearth_economy.account WHERE realm_id=?")){st.setObject(1,e.settings.realm());try(var row=st.executeQuery()){row.next();return row.getLong(1)==0;}}}),e.owner)).thenAccept(ok->check(p,ok,"autonomous_market_does_not_create_player_accounts_or_mint_currency"));}
 private static CompletionStage<Void> resume(JavaPlugin p,SurvivalEconomy e,Path root){var expected=new Properties();try(var r=Files.newBufferedReader(root.resolve("market-expected.properties"))){expected.load(r);}catch(Exception error){return CompletableFuture.failedFuture(error);}var opened=e.market().opened();check(p,opened.tick()==Long.parseLong(expected.getProperty("tick"))&&opened.mode().name().equals(expected.getProperty("mode"))&&opened.since()==Long.parseLong(expected.getProperty("since_tick"))&&opened.candidate().name().equals(expected.getProperty("candidate"))&&opened.votes()==Integer.parseInt(expected.getProperty("votes"))&&opened.revision()==Long.parseLong(expected.getProperty("revision")),"new_JVM_restores_exact_controller_mode_votes_and_clock_without_offline_ticks");if(e.market().settings().aiMode().equals("none"))check(p,e.market().director().status().equals("DISABLED"),"local_LLM_can_be_removed_without_reinitializing_market_policy");return on(e.store.modeHistory(e.settings.realm(),50),e.owner).thenAccept(rows->check(p,rows.stream().anyMatch(row->row.tick()==Long.parseLong(expected.getProperty("last_change"))),"mode_change_audit_survives_Paper_and_store_restart"));}
 private static CompletionStage<Void> ai(JavaPlugin p,SurvivalEconomy e,PostgresProgressStore db,Path root){if(!e.market().settings().aiMode().equals("ollama")||e.market().director().status().equals("NOT_PREPARED"))return CompletableFuture.failedFuture(new IllegalStateException("MARKET_REAL_AI_NOT_PREPARED"));CompletionStage<Void> setup=e.market().director().accepted()>0?CompletableFuture.completedFuture(null):shock(e,db,2);return setup.thenCompose(v->waitFor(p,()->e.market().director().accepted()>0||e.market().director().rejected()>0,0,180)).thenRun(()->{var result=new com.google.gson.JsonObject();result.addProperty("real_model",e.market().director().accepted()>0&&e.market().director().rejected()==0);result.addProperty("failure",e.market().director().lastFailure());result.addProperty("accepted",e.market().director().accepted());result.addProperty("rejected",e.market().director().rejected());result.addProperty("scope","numeric_market_aggregates_and_fixed_profile_codes_only");try{Files.writeString(root.resolve("market-ai-result.json"),result.toString()+"\n",StandardOpenOption.CREATE_NEW);}catch(Exception error){throw new IllegalStateException(error);}check(p,e.market().director().accepted()>0&&e.market().director().rejected()==0,"actual_pinned_local_LLM_returns_one_allowed_market_profile_code");});}
}
